84		// Use goldmark service for snippet generation
85		snippet, err := s.MarkdownService.GenerateSnippet([]byte(content), 64)
86		if err != nil {
87			return "", errors.Wrap(err, "failed to generate snippet")
88		}
89		return snippet, nil
